def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(x for row in g for x in row).most_common(1)[0][0]
    candidates = []
    for r, row in enumerate(g):
        if row and len(set(row)) == 1 and row[0] != bg:
            candidates.append(("h", r, row[0]))
    for c in range(w):
        vals = [g[r][c] for r in range(h)]
        if len(set(vals)) == 1 and vals[0] != bg:
            candidates.append(("v", c, vals[0]))
    if not candidates:
        return g
    # The full-length line is the reference; choose the first one if several exist.
    orient, line, line_color = candidates[0]
    if orient == "h":
        objs = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (bg, line_color)]
        if not objs:
            return g
        side = 1 if any(r > line for r, c in objs) else -1
        edge = max(r for r, c in objs) if side == 1 else min(r for r, c in objs)
        target = edge + side
        if 0 <= target < h:
            g[target] = [8] * w
    else:
        objs = [(r, c) for r in range(h) for c in range(w) if g[r][c] not in (bg, line_color)]
        if not objs:
            return g
        side = 1 if any(c > line for r, c in objs) else -1
        edge = max(c for r, c in objs) if side == 1 else min(c for r, c in objs)
        target = edge + side
        if 0 <= target < w:
            for r in range(h):
                g[r][target] = 8
    return g

